class WordDictionary {
private:
    struct Node {
        bool isWord;
        Node* child[26];
        Node() : isWord(false) {
            for (int i = 0; i < 26; ++i) child[i] = nullptr;
        }
    };
    Node* root;

    bool dfs(Node* node, const string& word, int idx) const {
        if (!node) return false;
        if (idx == (int)word.size()) return node->isWord;
        char c = word[idx];
        if (c != '.') {
            return dfs(node->child[c - 'a'], word, idx + 1);
        } else {
            for (int i = 0; i < 26; ++i) {
                if (node->child[i] && dfs(node->child[i], word, idx + 1))
                    return true;
            }
            return false;
        }
    }

public:
    WordDictionary() {
        root = new Node();
    }

    void addWord(string word) {
        Node* cur = root;
        for (char c : word) {
            int id = c - 'a';
            if (!cur->child[id]) cur->child[id] = new Node();
            cur = cur->child[id];
        }
        cur->isWord = true;
    }

    bool search(string word) {
        return dfs(root, word, 0);
    }
};
